package com.ruoyi.medical.persistence;
import com.ruoyi.medical.contracts.*;import java.util.*;import java.util.concurrent.atomic.AtomicBoolean;import javax.sql.DataSource;import org.springframework.jdbc.core.JdbcTemplate;
/** MODEL_RESULT fixed object intent derived only from a real dispatched mTLS outcome proof. */
public final class FormalInvocationObjectLedger {
 private final JdbcTemplate db;private final FormalInvocationSchema schema;private final int maximumBytes;
 public FormalInvocationObjectLedger(DataSource data,FormalInvocationSchema schema,int maximumBytes){this(new JdbcTemplate(data),schema,maximumBytes);}
 FormalInvocationObjectLedger(JdbcTemplate db,FormalInvocationSchema schema,int maximumBytes){this.db=db;db.setQueryTimeout(5);this.schema=schema;if(maximumBytes<1)throw new IllegalArgumentException();this.maximumBytes=maximumBytes;}
 public static final class Attempt implements RuntimeObjectAttempt {
  private final S3ObjectWriter.WriteIntent intent;private final byte[] content;private final String artifact,invocation,dispatch,kind,schemaRef,schemaHash,tenant,actor;private final boolean prior;private final AtomicBoolean consumed=new AtomicBoolean();
  private Attempt(S3ObjectWriter.WriteIntent intent,byte[] content,String artifact,String invocation,String dispatch,boolean prior,String kind,String schemaRef,String schemaHash,String tenant,String actor){this.tenant=tenant;this.actor=actor;this.kind=kind;this.schemaRef=schemaRef;this.schemaHash=schemaHash;this.intent=intent;this.content=content.clone();this.artifact=artifact;this.invocation=invocation;this.dispatch=dispatch;this.prior=prior;}
  public String tenantId(){return tenant;}public String actorId(){return actor;}public String expectedObjectKey(){return "formal/"+tenant+"/"+invocation+"/"+intent.writeId()+"/"+artifact;}
  public S3ObjectWriter.WriteIntent writeIntent(){return intent;}public byte[] bytes(){return content.clone();}public boolean priorAttempt(){return prior;}public TransferMode claimTransferMode(){return prior||!consumed.compareAndSet(false,true)?TransferMode.RECOVER_ONLY:TransferMode.INITIAL_WRITE;}
  String kind(){return kind;}String schemaRef(){return schemaRef;}String schemaSha256(){return schemaHash;}
  String plannedArtifact(){return artifact;}String invocationId(){return invocation;}String dispatchAttemptId(){return dispatch;}
 }
 public Attempt prepare(FormalInvocationOutcomeAuthority.VerifiedOutcome proof)throws Exception{return preparePayload(proof,proof.bytes(),"MODEL_RESULT",proof.schemaRef(),proof.schemaSha256());}
 public Attempt prepareCapture(FormalInvocationOutcomeAuthority.VerifiedOutcome proof,FormalProviderCaptureEvidence.Verified capture)throws Exception{capture.requireActive();if(!proof.invocationId().equals(capture.invocationId())||!proof.attemptId().equals(capture.attemptId()))bad();return preparePayload(proof,capture.bytes(),"PROVIDER_CAPTURE",capture.schemaRef(),capture.schemaSha256());}
 private Attempt preparePayload(FormalInvocationOutcomeAuthority.VerifiedOutcome proof,byte[] content,String kind,String schemaRef,String schemaHash)throws Exception{
  if(!org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive()||!TenantScope.requireCurrent().tenantId().equals(proof.tenantId())||!TenantScope.requireCurrent().subjectId().equals(proof.actorId()))throw new TenantAccessException(ErrorCode.ACCESS_DENIED);
  proof.requireActive();if(content.length<1||content.length>maximumBytes)throw new TenantAccessException(ErrorCode.CONTEXT_LIMIT);String sha=WireValues.sha256(content);var existing=read(proof,kind);
  if(existing.isEmpty()){
   String write=UUID.randomUUID().toString(),artifact=UUID.randomUUID().toString(),key="formal/"+proof.tenantId()+"/"+proof.invocationId()+"/"+write+"/"+artifact;
   one(db.update("INSERT INTO formal_invocation_object_intent(tenant_id,project_id,invocation_id,dispatch_attempt_id,write_id,artifact_id,object_key,object_sha256,size_bytes,canonical_payload,kind,schema_ref,payload_schema_sha256,outcome_binding_sha256,schema_version,schema_manifest_sha256,created_by,created_at,classification) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,'1.0.0',?,?,UTC_TIMESTAMP(6),?)",proof.tenantId(),proof.projectId(),proof.invocationId(),proof.attemptId(),write,artifact,key,sha,content.length,new String(content,java.nio.charset.StandardCharsets.UTF_8),kind,schemaRef,schemaHash,proof.bindingSha256(),schema.manifestSha256(),proof.actorId(),proof.classification()));one(db.update("INSERT INTO formal_invocation_object_state(tenant_id,write_id,stage,revision,schema_version,schema_manifest_sha256,created_by,created_at,classification,updated_at) VALUES(?,?,'PREPARED',1,'1.0.0',?,?,UTC_TIMESTAMP(6),?,UTC_TIMESTAMP(6))",proof.tenantId(),write,schema.manifestSha256(),proof.actorId(),proof.classification()));existing=read(proof,kind);
  }
  var row=one(existing);if(!row.sha().equals(sha)||!Arrays.equals(row.content().getBytes(java.nio.charset.StandardCharsets.UTF_8),content)||!row.binding().equals(proof.bindingSha256())||!row.schemaRef().equals(schemaRef)||!row.schemaHash().equals(schemaHash)||!row.key().equals("formal/"+proof.tenantId()+"/"+proof.invocationId()+"/"+row.write()+"/"+row.artifact())||row.size()!=content.length)bad();
  var attempts=db.query("SELECT write_id FROM formal_invocation_object_attempt WHERE tenant_id=? AND write_id=? AND invocation_id=? AND dispatch_attempt_id=? AND created_by=? AND schema_version='1.0.0' AND schema_manifest_sha256=? LIMIT 2 FOR UPDATE",(r,n)->r.getString(1),proof.tenantId(),row.write(),proof.invocationId(),proof.attemptId(),proof.actorId(),schema.manifestSha256());if(attempts.size()>1)bad();boolean prior=!attempts.isEmpty();String stage=one(db.query("SELECT stage FROM formal_invocation_object_state WHERE tenant_id=? AND write_id=? AND schema_version='1.0.0' AND schema_manifest_sha256=? AND created_by=? AND classification=? AND ((stage='PREPARED' AND revision=1) OR (stage='ATTEMPTED' AND revision=2)) LIMIT 2 FOR UPDATE",(r,n)->r.getString(1),proof.tenantId(),row.write(),schema.manifestSha256(),proof.actorId(),proof.classification()));if(prior&&!"ATTEMPTED".equals(stage)||!prior&&!"PREPARED".equals(stage))bad();if(!prior){one(db.update("INSERT INTO formal_invocation_object_attempt(tenant_id,write_id,invocation_id,dispatch_attempt_id,schema_version,schema_manifest_sha256,created_by,created_at,classification) VALUES(?,?,?,?,'1.0.0',?,?,UTC_TIMESTAMP(6),?)",proof.tenantId(),row.write(),proof.invocationId(),proof.attemptId(),schema.manifestSha256(),proof.actorId(),proof.classification()));one(db.update("UPDATE formal_invocation_object_state SET stage='ATTEMPTED',revision=2,updated_at=UTC_TIMESTAMP(6) WHERE tenant_id=? AND write_id=? AND stage='PREPARED' AND revision=1",proof.tenantId(),row.write()));}
  return new Attempt(new S3ObjectWriter.WriteIntent(row.write(),row.key(),sha,Integer.toString(content.length),"application/json"),content,row.artifact(),proof.invocationId(),proof.attemptId(),prior,kind,schemaRef,schemaHash,proof.tenantId(),proof.actorId());
 }
 private record Row(String write,String artifact,String key,String sha,int size,String content,String schemaRef,String schemaHash,String binding){}
 private List<Row> read(FormalInvocationOutcomeAuthority.VerifiedOutcome p,String kind){return db.query("SELECT write_id,artifact_id,object_key,object_sha256,size_bytes,canonical_payload,schema_ref,payload_schema_sha256,outcome_binding_sha256 FROM formal_invocation_object_intent WHERE tenant_id=? AND project_id=? AND invocation_id=? AND dispatch_attempt_id=? AND kind=? AND created_by=? AND schema_version='1.0.0' AND schema_manifest_sha256=? LIMIT 2 FOR UPDATE",(r,n)->new Row(r.getString(1),r.getString(2),r.getString(3),r.getString(4),r.getInt(5),r.getString(6),r.getString(7),r.getString(8),r.getString(9)),p.tenantId(),p.projectId(),p.invocationId(),p.attemptId(),kind,p.actorId(),schema.manifestSha256());}
 private static <T>T one(List<T> r){if(r.size()!=1||r.get(0)==null)bad();return r.get(0);}private static void one(int n){if(n!=1)bad();}private static void bad(){throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}
}
